async function rpcOk(api: Api, name: string, args: Record<string, unknown>) {
  const res = await api.rpc(name, args);
  const body = await res.text();
  expect(res.ok(), `${name}: ${res.status()} ${body}`).toBeTruthy();
  return body ? JSON.parse(body) : null;
}

type SimState = { status: string; threshold_checklist: unknown; threshold_checked_by: unknown; threshold_checked_at: unknown };

async function simState(api: Api, id: string): Promise<SimState> {
  const res = await api.get(`simulations?select=status,threshold_checklist,threshold_checked_by,threshold_checked_at&id=eq.${id}`);
  expect(res.ok(), `simulations: ${res.status()}`).toBeTruthy();
  const rows = (await res.json()) as SimState[];
  expect(rows, `симуляция ${id} не найдена`).toHaveLength(1);
  return rows[0];
}

/** Страховка: симуляция не должна стать активной. Если стала — сразу «לא פעילה» и падение теста. */
async function expectNotActivated(api: Api, id: string) {
  const s = await simState(api, id);
  if (s.status === 'active') {
    await api.rpc('set_simulation_status', { p_simulation_id: id, p_status: 'inactive', p_confirm_pilot_overrun: false });
  }
  expect(s.status, 'симуляция активирована без подтверждения — возвращена в «לא פעילה»').toBe('pending_approval');
  expect(s.threshold_checklist ?? null, 'отметки сохранены без утверждения').toBeNull();
}

/** Своя симуляция с шагами 1–4 и черновиком сценария → «העברה לאישור» через UI. Возвращает id. */
async function createPendingSimulation(page: Page, api: Api, name: string): Promise<string> {
  const created = await rpcOk(api, 'save_simulation', {
    p_simulation_id: null,
    p_fields: {
      name,
      role_title: SIM.role_title,
      industry: SIM.industry,
      product_or_service: SIM.product_or_service,
      target_audience: SIM.target_audience,
      call_goal: SIM.call_goal,
      customer_type: 'warm_lead',
      language: 'he',
      duration_minutes: 7,
      desired_outcome: SIM.desired_outcome,
      desired_next_step: 'consultation_meeting',
      end_conditions: null,
    },
  });
  const id = created.id as string;
  expect(created.status).toBe('draft');
  test.info().annotations.push({ type: 'test-data', description: `симуляция «${name}» ${id} (ממתינה לאישור), не удаляется` });
  await rpcOk(api, 'save_simulation', {
    p_simulation_id: id,
    p_fields: {
      customer_opening_state: 'סקרן אבל חשדן',
      customer_need: 'חשבון חשמל גבוה מאוד בקיץ',
      prior_relationship: null,
      info_items: [
        { text: 'בעל הבית גר בבית פרטי עם משפחה של חמש נפשות', tier: 'shown_upfront', reveal_condition: null },
        { text: 'באוגוסט שילם חשבון חשמל של אלף ושמונה מאות שקלים', tier: 'discover_in_call', reveal_condition: null },
      ],
    },
  });
  await rpcOk(api, 'save_simulation', {
    p_simulation_id: id,
    p_fields: {
      objection_source: 'free_text',
      main_objection: SIM.main_objection,
      objection_reason: 'חושש להתחייב להוצאה גדולה בתקופה לא יציבה',
      objection_discoverable_info: 'זכאי להלוואה ירוקה בריבית נמוכה',
      softening_conditions: 'המועמד מציג חישוב החזר חודשי שנמוך מחשבון החשמל',
      refusal_conditions: 'המועמד לוחץ לסגור עסקה בשיחה הראשונה',
    },
  });
  await rpcOk(api, 'save_simulation', {
    p_simulation_id: id,
    p_fields: {
      offer_allowed_info: 'אחריות של עשרים וחמש שנה על הפאנלים',
      offer_required_info: 'ההתקנה דורשת אישור חברת החשמל',
      offer_benefits: 'חיסכון בחשבון החשמל',
      offer_price: null,
      offer_forbidden_info: 'אין להמציא מענקים ממשלתיים',
      offer_forbidden_promises: 'אסור להבטיח החזר תוך שנה',
    },
  });
  if (USE_AI) {
    const res = await page.request.post(`${SUPABASE_URL}/functions/v1/generate-scenario-draft`, {
      headers: api.headers,
      data: { simulation_id: id },
      timeout: 180_000,
    });
    const body = await res.text();
    expect(res.ok(), `generate-scenario-draft: ${res.status()} ${body}`).toBeTruthy();
  } else {
    await rpcOk(api, 'save_scenario_draft', { p_simulation_id: id, p_fields: MANUAL_DRAFT });
  }

  await page.goto(`/simulations/${id}/draft`);
  const submit = page.waitForResponse((r) => r.url().includes('/rest/v1/rpc/submit_simulation_for_approval'));
  await page.getByRole('button', { name: 'העברה לאישור' }).click();
  const res = await submit;
  expect(res.status(), `submit_simulation_for_approval: ${await res.text()}`).toBe(200);
  await expect.poll(async () => (await simState(api, id)).status).toBe('pending_approval');
  await page.reload();
  await expect(page.getByRole('heading', { name: 'בדיקת סף לפני הפעלה' })).toBeVisible();
  return id;
}

const checkbox = (page: Page, label: string) => page.getByRole('checkbox', { name: label, exact: true });
const item = (page: Page, key: string) => page.getByTestId('threshold-item').and(page.locator(`[data-item="${key}"]`));
const counter = (page: Page) => page.getByTestId('threshold-counter');
const approveButton = (page: Page) => page.getByRole('button', { name: 'אישור והפעלה' });

test.describe(`Порог перед активацией и рамка пилота (${TAG})`, () => {
  test(`«בדיקת סף לפני הפעלה»: 7 пунктов не отмечены с пояснением и ссылкой на шаг; неотмеченный пункт блокирует утверждение (UI и сервер); уровней сложности нет @desktop @data ${TAG}`, async ({ asUser }) => {
    test.setTimeout(USE_AI ? 300_000 : 120_000);
    const page = await asUser('business');
    await blockScenarioGeneration(page);
    const api = await openWithApi(page, '/simulations');
    const name = `QA-AUTO-a2c2d9-${runStamp()}`;

    const approveCalls: string[] = [];
    page.on('request', (r) => {
      if (r.url().includes('/rest/v1/rpc/approve_simulation')) approveCalls.push(r.postData() ?? '');
    });

    const id = await test.step('своя симуляция → «ממתינה לאישור»', () => createPendingSimulation(page, api, name));

    await test.step('THR-001: счётчик «0 מתוך 7», 7 пунктов по порядку, все не отмечены, пояснение + значение + ссылка на шаг', async () => {
      await expect(counter(page)).toHaveText('0 מתוך 7');
      const items = page.getByTestId('threshold-item');
      await expect(items).toHaveCount(7);
      for (let i = 0; i < ITEMS.length; i++) {
        const it = ITEMS[i];
        await expect(items.nth(i)).toHaveAttribute('data-item', it.key);
        const row = item(page, it.key);
        await expect(checkbox(page, it.label)).not.toBeChecked();
        await expect(row.getByTestId('threshold-explanation')).toHaveText(it.explanation);
        await expect(row).toContainText(it.value);
        await expect(row.getByRole('link', { name: it.link })).toHaveAttribute('href', `/simulations/${id}?step=${it.step}&field=${it.field}`);
      }
      // В testim есть активные симуляции — заметки «первый сценарий бизнеса» быть не должно (FL-19 шаг 2).
      await expect(page.getByText(FIRST_SCENARIO_NOTE)).toHaveCount(0);
    });

    await test.step('THR-001: отмеченный пункт сворачивается (без пояснения и ссылки), снятие — разворачивает', async () => {
      const first = ITEMS[0];
      await checkbox(page, first.label).check({ force: true });
      await expect(counter(page)).toHaveText('1 מתוך 7');
      await expect(item(page, first.key).getByTestId('threshold-explanation')).toHaveCount(0);
      await expect(item(page, first.key).getByRole('link')).toHaveCount(0);
      await checkbox(page, first.label).uncheck({ force: true });
      await expect(counter(page)).toHaveText('0 מתוך 7');
      await expect(item(page, first.key).getByTestId('threshold-explanation')).toHaveText(first.explanation);
    });

    await test.step('THR-002: для каждого из 7 пунктов — отмечены остальные 6 → «אישור והפעלה» → «האישור נחסם» с названием именно этого пункта, запрос не уходит', async () => {
      for (const it of ITEMS) await checkbox(page, it.label).check({ force: true });
      await expect(counter(page)).toHaveText('7 מתוך 7');
      for (const missing of ITEMS) {
        await checkbox(page, missing.label).uncheck({ force: true });
        await expect(counter(page)).toHaveText('6 מתוך 7');
        await approveButton(page).click();
        const blocked = page.getByRole('alert').filter({ hasText: 'יש לסמן את הפריטים הבאים לפני האישור' });
        await expect(blocked).toContainText('האישור נחסם');
        await expect(blocked).toContainText(`יש לסמן את הפריטים הבאים לפני האישור: ${missing.label}.`);
        await checkbox(page, missing.label).check({ force: true });
        await expect(blocked).toHaveCount(0);
      }
      expect(approveCalls, 'approve_simulation ушёл при неотмеченном пункте').toHaveLength(0);
      // Вернуть панель в исходное состояние, ничего не утверждая.
      for (const it of ITEMS) await checkbox(page, it.label).uncheck({ force: true });
      await expect(counter(page)).toHaveText('0 מתוך 7');
      await expectNotActivated(api, id);
    });

    await test.step('THR-002: сервер — approve_simulation с comparability=false → 400 threshold_incomplete, статус не меняется', async () => {
      const threshold = Object.fromEntries(ITEMS.map((it) => [it.key, it.key !== 'comparability']));
      // p_confirm_pilot_overrun=true — как при проверке 21.10: так сервер проверяет именно порог, а не рамку пилота.
      const res = await api.rpc('approve_simulation', { p_simulation_id: id, p_threshold: threshold, p_confirm_pilot_overrun: true });
      const body = await res.text();
      await expectNotActivated(api, id);
      expect(res.status(), body).toBe(400);
      const err = JSON.parse(body) as { message: string; details: string | null };
      expect(err.message).toBe('threshold_incomplete: comparability');
      expect(err.details).toBe('comparability');
    });

    await test.step('THR-006: «קושי» нет ни на «סקירת הטיוטה», ни в 4 шагах редактора; в записи нет поля difficulty', async () => {
      await expect(page.getByText(/קושי/)).toHaveCount(0);
      for (const step of ['general', 'customer', 'objection', 'offer']) {
        await page.goto(`/simulations/${id}?step=${step}`);
        await expect(page.getByRole('main')).toBeVisible();
        await expect(page.getByText(/קושי/)).toHaveCount(0);
      }
      const res = await api.get(`simulations?select=*&id=eq.${id}`);
      expect(res.ok()).toBeTruthy();
      const [row] = (await res.json()) as Record<string, unknown>[];
      expect(Object.keys(row).filter((k) => /difficult/i.test(k))).toEqual([]);
    });
  });

  test(`вторая активная симуляция: «אישור והפעלה» → 400 pilot_scope_exceeded, диалог «חריגה מהיקף הפיילוט המומלץ», «ביטול» — остаётся «ממתינה לאישור» @desktop @data ${TAG}`, async ({ asUser }) => {
    test.setTimeout(USE_AI ? 300_000 : 120_000);
    const page = await asUser('business');
    await blockScenarioGeneration(page);
    const api = await openWithApi(page, '/simulations');

    // Без активной симуляции в бизнесе утверждение АКТИВИРУЕТ черновик — такой прогон запрещён.
    const activeRes = await api.get('simulations?select=id&status=eq.active');
    expect(activeRes.ok()).toBeTruthy();
    const active = (await activeRes.json()) as { id: string }[];
    test.skip(active.length === 0, 'в бизнесе нет активной симуляции — утверждение активировало бы черновик');

    const name = `QA-AUTO-a2c2d9-${runStamp()}`;
    const id = await test.step('своя симуляция → «ממתינה לאישור»', () => createPendingSimulation(page, api, name));

    const approveCalls: string[] = [];
    page.on('request', (r) => {
      if (r.url().includes('/rest/v1/rpc/approve_simulation')) approveCalls.push(r.postData() ?? '');
    });

    await test.step('все 7 отмечены → «אישור והפעלה» → 400 pilot_scope_exceeded без подтверждения', async () => {
      for (const it of ITEMS) await checkbox(page, it.label).check({ force: true });
      await expect(counter(page)).toHaveText('7 מתוך 7');
      const approve = page.waitForResponse((r) => r.url().includes('/rest/v1/rpc/approve_simulation'));
      await approveButton(page).click();
      const res = await approve;
      const body = await res.text();
      if (res.ok()) await expectNotActivated(api, id);
      expect(res.status(), body).toBe(400);
      const err = JSON.parse(body) as { message: string; hint: string | null };
      expect(err.message).toBe('pilot_scope_exceeded');
      expect(err.hint).toBe('confirm_with_p_confirm_pilot_overrun');
      const sent = JSON.parse(res.request().postData() ?? '{}') as { p_confirm_pilot_overrun?: boolean; p_threshold?: Record<string, boolean> };
      expect(sent.p_confirm_pilot_overrun).toBe(false);
      expect(Object.values(sent.p_threshold ?? {}).filter(Boolean)).toHaveLength(7);
    });

    await test.step('диалог «חריגה מהיקף הפיילוט המומלץ» → «ביטול»: закрыт, повторного запроса нет, не активна', async () => {
      const dialog = page.getByRole('dialog').or(page.getByRole('alertdialog'));
      await expect(dialog).toBeVisible();
      await expect(dialog).toContainText('חריגה מהיקף הפיילוט המומלץ');
      await expect(dialog).toContainText(PILOT_DIALOG_TEXT);
      await expect(dialog.getByRole('button', { name: 'הפעלה בכל זאת' })).toBeVisible();
      await dialog.getByRole('button', { name: 'ביטול' }).click();
      await expect(dialog).toBeHidden();
      expect(approveCalls, 'после «ביטול» ушёл ещё один approve_simulation').toHaveLength(1);
      await expectNotActivated(api, id);
    });
  });
});
